'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var isNegativeZero = require( '@stdlib/math/base/assert/is-negative-zero' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var roundsdf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( roundsdf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof roundsdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'returns NaN for NaN inputs', opts, function test( t ) {
	t.ok( isnan( roundsdf( NaN, 2, 10 ) ), 'NaN input' );
	t.ok( isnan( roundsdf( 3.14, NaN, 10 ) ), 'NaN n' );
	t.end();
});

tape( 'returns NaN for n < 1', opts, function test( t ) {
	t.ok( isnan( roundsdf( 3.14, 0, 10 ) ), 'n = 0' );
	t.ok( isnan( roundsdf( 3.14, -1, 10 ) ), 'n < 0' );
	t.end();
});

tape( 'returns infinities unchanged', opts, function test( t ) {
	t.strictEqual( roundsdf( PINF, 3, 10 ), PINF, '+infinity' );
	t.strictEqual( roundsdf( NINF, 3, 10 ), NINF, '-infinity' );
	t.end();
});

tape( 'preserves signed zero', opts, function test( t ) {
	t.ok( isPositiveZero( roundsdf( 0.0, 2, 10 ) ), '+0 preserved' );
	t.ok( isNegativeZero( roundsdf( -0.0, 2, 10 ) ), '-0 preserved' );
	t.end();
});

tape( 'rounds to nearest with n significant figures', opts, function test( t ) {
	t.strictEqual( roundsdf( 3.141592653589793, 1, 10 ), 3.0, 'n=1' );
	t.strictEqual( roundsdf( 3.141592653589793, 2, 10 ), 3.1, 'n=2' );
	t.strictEqual( roundsdf( 3.141592653589793, 3, 10 ), 3.14, 'n=3' );
	t.end();
});

tape( 'rounds large and negative values correctly', opts, function test( t ) {
	var expected;
	var delta;
	var tol;
	var v;

	expected = 10000.0;
	v = roundsdf( 12368.0, 1, 10 );
	delta = abs( v - expected );
	tol = max( 1.0e-3, EPS * abs( expected ) );
	t.ok( delta <= tol, 'large positive within tolerance' );

	expected = -12000.0;
	v = roundsdf( -12368.0, 2, 10 );
	delta = abs( v - expected );
	tol = max( 1.0e-3, EPS * abs( expected ) );
	t.ok( delta <= tol, 'large negative within tolerance' );

	t.end();
});
